"""Generates Supplementary Tables TS1-TS14 (LaTeX, booktabs + longtable) from authoritative saved results (read-only via git show).
No value is recomputed beyond re-expression (percent scaling, rounding, labelling). Missing intervals are shown as n/a."""
import sys, pathlib, json, numpy as np, pandas as pd
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent)); from pubstyle import csv, js, SUP, wilson
E = "experiments/"; OUT = SUP / "tables"; OUT.mkdir(exist_ok=True)
def esc(x):
    if isinstance(x, str):
        for a, b in (("\\", r"\textbackslash{}"), ("&", r"\&"), ("%", r"\%"), ("_", r"\_"), ("#", r"\#"), (">=", r"$\geq$"), ("<=", r"$\leq$"), ("->", r"$\rightarrow$"), ("~", r"\textasciitilde{}"), ("^2", r"$^{2}$"), ("|ratio|", r"$|$ratio$|$")):
            x = x.replace(a, b)
        return x
    return x
def f(v, d=4):
    if v is None or (isinstance(v, float) and not np.isfinite(v)): return "n/a"
    if isinstance(v, (bool, np.bool_)): return "yes" if v else "no"
    if isinstance(v, (int, np.integer)): return f"{v:,}"
    v = 0.0 if round(float(v), d) == 0 else v                              # no "-0.000"
    return f"{v:.{d}f}"
def ci(lo, hi, d=4): return "n/a" if (lo is None or not np.isfinite(lo)) else f"{lo:.{d}f} to {hi:.{d}f}"
P = lambda w: r">{\raggedright\arraybackslash}p{" + str(w) + r"\textwidth}"
def write(tid, title, status, cols, rows, notes, align=None, size=r"\footnotesize", parts=None):
    align = align or "l" + "r" * (len(cols) - 1)
    L = [f"% {tid}: generated by publication/supplementary/scripts/make_tables.py from authoritative results; do not edit by hand", r"\begingroup" + size,
         r"\setlength{\LTcapwidth}{\textwidth}", rf"\begin{{longtable}}{{@{{}}{align}@{{}}}}", rf"\caption{{\textbf{{{esc(title)}}} {esc(status)}}}\label{{tab:{tid}}}\\", r"\toprule",
         " & ".join(esc(c) for c in cols) + r" \\", r"\midrule", r"\endfirsthead", r"\toprule", " & ".join(esc(c) for c in cols) + r" \\", r"\midrule", r"\endhead",
         r"\bottomrule", r"\endfoot"]
    for r in rows:
        if isinstance(r, str): L.append(rf"\midrule \multicolumn{{{len(cols)}}}{{@{{}}l}}{{\textit{{{esc(r)}}}}} \\ \midrule")
        else: L.append(" & ".join(esc(str(x)) for x in r) + r" \\")
    L += [r"\end{longtable}", r"\par\vspace{-4pt}\noindent\begin{minipage}{\textwidth}\scriptsize " + " ".join(esc(n) for n in notes) + r"\end{minipage}", r"\endgroup"]
    (OUT / f"{tid}.tex").write_text("\n".join(L) + "\n"); return len(rows)

